            case 'pro-tips':
                return <ProTips />;
            case 'config-generator':
                return <ConfigGenerator />;
            case 'gfx-tool':
                return <GfxTool />;
            case 'system-optimizer':
                return <SystemOptimizer />;
            case 'profile':
                return <DeviceProfile />;
            case 'settings':
                return <Settings isFxEnabled={isFxEnabled} toggleFx={toggleFx} />;
