            </div>
        </main>

        {/* --- Footer (Non-scrollable, fixed at bottom) --- */}
        <footer className="container mx-auto max-w-7xl text-center text-xs text-[#00ff41]/60 p-2 border-t border-[#00ff41]/20 flex justify-between items-center shrink-0">
