                <a href={SPONSORS[currentSponsor].link} target="_blank" rel="noopener noreferrer" className="font-bold text-sm hover:underline" title={`Visit ${SPONSORS[currentSponsor].name}`}>
                    {SPONSORS[currentSponsor].name}
