     </>
   );
 };

 export default App;

import React, { useState } from 'react';
import { clearHistory, clearDeviceProfile } from '../utils/storage';
import { ConfirmationDialog } from './common/ConfirmationDialog';
import { Button } from './common/Button';

interface SettingsProps {
    isFxEnabled: boolean;
    toggleFx: () => void;
}

export const Settings: React.FC<SettingsProps> = ({ isFxEnabled, toggleFx }) => {
    const [isHistoryConfirmOpen, setIsHistoryConfirmOpen] = useState(false);
    const [isProfileConfirmOpen, setIsProfileConfirmOpen] = useState(false);
    const [feedback, setFeedback] = useState('');

    const showTempFeedback = (message: string) => {
        setFeedback(message);
        setTimeout(() => setFeedback(''), 3000);
    };

    const handleClearHistory = () => {
        clearHistory();
        showTempFeedback('Generation history has been cleared.');
    };

    const handleClearProfile = () => {
        clearDeviceProfile();
        showTempFeedback('Saved device profile has been cleared.');
    };

    return (
        <section className="panel-glass p-6 space-y-8 max-w-4xl mx-auto">
            <h2 className="text-3xl uppercase tracking-wider text-center">Settings</h2>

            {/* Appearance Settings */}
            <fieldset className="border border-[#00ff41]/30 p-4 space-y-4">
                <legend className="px-2 text-xl">Appearance</legend>
                <div className="flex justify-between items-center">
                    <label htmlFor="fx-toggle" className="text-lg">Enable Visual Effects:</label>
                    <button
                        id="fx-toggle"
                        onClick={toggleFx}
                        className={`relative inline-flex items-center h-6 rounded-full w-11 transition-colors duration-300 ${isFxEnabled ? 'bg-[#00ff41]' : 'bg-black/50'}`}
                    >
                        <span className={`inline-block w-4 h-4 transform bg-white rounded-full transition-transform duration-300 ${isFxEnabled ? 'translate-x-6' : 'translate-x-1'}`} />
                    </button>
                </div>
                <p className="text-sm text-[#00ff41]/60">
                    Disabling visual effects like the matrix background may improve performance on low-end devices.
                </p>
            </fieldset>

            {/* Data Management */}
            <fieldset className="border border-[#00ff41]/30 p-4 space-y-4">
                <legend className="px-2 text-xl">Data Management</legend>
                <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                    <p className="text-lg">Clear all generation history:</p>
                    <button onClick={() => setIsHistoryConfirmOpen(true)} className="w-full sm:w-auto bg-red-900/50 border border-red-500 px-4 py-2 text-sm hover:bg-red-700/50 transition-colors uppercase tracking-wider">
                        Clear History
                    </button>
                </div>
                 <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                    <p className="text-lg">Clear saved device profile:</p>
                    <button onClick={() => setIsProfileConfirmOpen(true)} className="w-full sm:w-auto bg-red-900/50 border border-red-500 px-4 py-2 text-sm hover:bg-red-700/50 transition-colors uppercase tracking-wider">
                        Clear Profile
                    </button>
                </div>
            </fieldset>

            {/* About Section */}
            <fieldset className="border border-[#00ff41]/30 p-4 text-center">
                <legend className="px-2 text-xl">About</legend>
                <h3 className="text-2xl font-bold">trouble.exe</h3>
                <p className="text-[#00ff41]/80">Version 1.2.5 (Stable)</p>
                <p className="mt-2 text-[#00ff41]/70">An AI-powered assistant for FF gamers. Get pro tips and generate custom headshot configuration files to improve your gameplay.</p>
            </fieldset>

            {feedback && (
                 <div className="text-center p-2 bg-black/50 border border-[#00ff41]/30">
                    {feedback}
                </div>
            )}

            <ConfirmationDialog
                isOpen={isHistoryConfirmOpen}
                onClose={() => setIsHistoryConfirmOpen(false)}
                onConfirm={handleClearHistory}
                title="Confirm Clear History"
            >
                 <p>Are you sure you want to permanently delete all your generated history? This action cannot be undone.</p>
            </ConfirmationDialog>

            <ConfirmationDialog
                isOpen={isProfileConfirmOpen}
                onClose={() => setIsProfileConfirmOpen(false)}
                onConfirm={handleClearProfile}
                title="Confirm Clear Profile"
            >
                <p>Are you sure you want to delete your saved device profile? You will need to enter your details again.</p>
            </ConfirmationDialog>
        </section>
    );
};

