export const AdBanner: React.FC = () => {
    const adRef = useRef<HTMLDivElement>(null);
    const observerRef = useRef<IntersectionObserver | null>(null);
    const [randomDeal, setRandomDeal] = useState(GAMER_DEALS[0]);
    const [showAdSense, setShowAdSense] = useState(false); // Toggle between Affiliate and AdSense

    useEffect(() => {
        // Pick a random deal on mount
        setRandomDeal(GAMER_DEALS[Math.floor(Math.random() * GAMER_DEALS.length)]);

        // Randomly decide whether to show AdSense or a Custom Deal (70% AdSense, 30% Custom)
        setShowAdSense(Math.random() > 0.3);
    }, []);

    useEffect(() => {
        if (!showAdSense) return;

        if (observerRef.current) {
            observerRef.current.disconnect();
        }

        observerRef.current = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    try {
                        ((window as any).adsbygoogle = (window as any).adsbygoogle || []).push({});
                    } catch (e) {
                        console.error("AdSense push error:", e);
                    }
                    if (adRef.current && observerRef.current) {
                        observerRef.current.unobserve(adRef.current);
                    }
                }
            },
            { threshold: 0.01 }
        );

        if (adRef.current) {
            observerRef.current.observe(adRef.current);
        }

        return () => {
            if (observerRef.current) {
                observerRef.current.disconnect();
            }
        };
    }, [showAdSense]);

    return (
        <section className="panel-glass p-6 space-y-4 max-w-4xl mx-auto overflow-hidden relative" aria-label="Gamer Deal">
            <div className="flex justify-between items-center border-b border-[#00ff41]/20 pb-2">
                <h2 className="text-xs uppercase tracking-[0.3em] text-[#00ff41]/60">
                    {showAdSense ? "// Network Ad //" : "// Direct Gamer Deal //"}
                </h2>
                {!showAdSense && <span className="animate-pulse text-[10px] text-yellow-400 font-bold px-2 py-0.5 border border-yellow-500/50">LIMITED TIME</span>}
            </div>

            <div className="bg-black/40 border border-[#00ff41]/10 p-4 min-h-[120px] flex flex-col justify-center items-center transition-all duration-500 hover:bg-[#00ff41]/5">
                {showAdSense ? (
                    <div ref={adRef} className="w-full">
                        <ins className="adsbygoogle"
                             style={{ display: 'block', width: '100%' }}
                             data-ad-client="ca-pub-9999999999999999"
                             data-ad-slot="8888888888"
                             data-ad-format="auto"
                             data-full-width-responsive="true"></ins>
                    </div>
                ) : (
                    <div className="text-center space-y-2 w-full animate-in fade-in zoom-in duration-700">
                        <p className="text-[#00ff41]/60 text-xs tracking-widest">{randomDeal.provider}</p>
                        <h3 className="text-2xl font-bold text-white tracking-wide">{randomDeal.title}</h3>
                        <p className="text-[#00ff41]/80 text-sm italic">"{randomDeal.description}"</p>
                        <a 
                            href={randomDeal.link} 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="inline-block mt-4 bg-[#00ff41]/10 border border-[#00ff41] px-6 py-2 text-sm uppercase tracking-widest hover:bg-[#00ff41] hover:text-black transition-all duration-300 transform hover:scale-105"
                        >
                            Claim Deal &gt;&gt;
                        </a>
                    </div>
                )}
            </div>

            {/* Matrix Decorative Elements */}
            <div className="absolute top-0 right-0 p-1 opacity-10 pointer-events-none text-[8px] font-mono leading-none">
                01010101<br/>10101010<br/>01010101
            </div>
        </section>
    );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
