type DeviceProfile = "Ultra Low-Spec (1GB RAM)" | "Low-End" | "Mid-Range" | "High-End" | "Unknown";

const OPTIMIZER_LOADING_MESSAGES = [
    "Scanning kernel parameters...",
    "Analyzing system services...",
    "Compiling optimization checklist...",
    "Generating ADB command script...",
    "Building step-by-step visual guides...",
];

export const SystemOptimizer: React.FC = () => {
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<ErrorAnalysis | null>(null);
    const [plan, setPlan] = useState<SystemOptimizationPlan | null>(null);
    const [loadingMessage, setLoadingMessage] = useState('Initializing...');
    const [deviceProfile, setDeviceProfile] = useState<DeviceProfile>("Unknown");
    const [selectedStep, setSelectedStep] = useState<OptimizationStep | null>(null);
    const { showFeedback } = useFeedback();

    useEffect(() => {
        const detectProfile = () => {
            // Safari/iOS doesn't support deviceMemory. Use user agent as fallback.
            const ram = (navigator as any).deviceMemory;
            const ua = navigator.userAgent.toLowerCase();

            if (ram !== undefined) {
                if (ram <= 1.5) setDeviceProfile("Ultra Low-Spec (1GB RAM)");
                else if (ram < 4) setDeviceProfile("Low-End");
                else if (ram < 6) setDeviceProfile("Mid-Range");
                else setDeviceProfile("High-End");
            } else if (ua.includes('iphone') || ua.includes('ipad')) {
                // Approximate for iOS
                setDeviceProfile("Mid-Range");
            } else {
                setDeviceProfile("Mid-Range"); // Default for browsers blocking hardware info
            }
        };
        detectProfile();
    }, []);

    useEffect(() => {
        if (deviceProfile === "Unknown") return;
        const cacheKey = getCacheKey('system-plan', deviceProfile);
        const cachedPlan = getCache<SystemOptimizationPlan>(cacheKey);
        if (cachedPlan) {
            setPlan(cachedPlan);
        }
    }, [deviceProfile]);

    const handleGeneratePlan = async () => {
        setIsLoading(true);
        setError(null);

        let messageIndex = 0;
        setLoadingMessage(OPTIMIZER_LOADING_MESSAGES[messageIndex]);
        const intervalId = setInterval(() => {
            messageIndex = (messageIndex + 1) % OPTIMIZER_LOADING_MESSAGES.length;
            setLoadingMessage(OPTIMIZER_LOADING_MESSAGES[messageIndex]);
        }, 1500);

        try {
            const response = await generateSystemOptimizations(deviceProfile);
            const parsedPlan: SystemOptimizationPlan = JSON.parse(response);
            setPlan(parsedPlan);

            const cacheKey = getCacheKey('system-plan', deviceProfile);
            setCache(cacheKey, parsedPlan);

            addHistoryItem({
                type: HistoryType.SYSTEM_PLAN,
                data: parsedPlan,
                timestamp: Date.now(),
                context: deviceProfile
            });
            showFeedback('Optimization Plan Updated Successfully!');
        } catch (e) {
            let errorMessage = e instanceof Error ? e.message : "Error";
            const analyzedError = await analyzeErrorAndSuggestSolution(errorMessage);
            setError(analyzedError);
        } finally {
            clearInterval(intervalId);
            setIsLoading(false);
        }
    };

    const handleCopyAllCommands = () => {
        if (plan?.adbCommands) {
            navigator.clipboard.writeText(plan.adbCommands);
            showFeedback('All ADB commands copied to clipboard!');
        }
    };

    return (
        <section className="panel-glass p-6 space-y-6 max-w-4xl mx-auto">
             <LoadingOverlay isLoading={isLoading} message={loadingMessage}>
                <AdBanner key="system-loading-ad" />
            </LoadingOverlay>

            <h2 className="text-3xl uppercase tracking-wider text-center">System Optimizer Co-Pilot</h2>
            <div className="text-center space-y-2">
                <p className="text-lg">This tool generates a personalized, step-by-step plan to tune your Android OS for maximum gaming performance.</p>
                <p className="text-sm text-[#00ff41]/70 bg-black/20 p-2 border border-[#00ff41]/20">
                    Detected Device Profile: <span className="font-bold">{deviceProfile}</span>
                </p>
            </div>

            <Button onClick={handleGeneratePlan} isLoading={isLoading}>
                {plan && !isLoading ? 'Refresh My Plan' : 'Generate My Optimization Plan'}
            </Button>

            {error && <ErrorDisplay error={error} />}

            <div aria-live="polite">
                {plan && (
                    <div className="space-y-8 mt-6">
                        <div>
                            <h3 className="text-2xl text-center mb-4">Optimization Checklist</h3>
                            <div className="space-y-3">
                                {plan.checklist.map((step, index) => (
                                    <div key={index} className="panel-glass p-4 flex justify-between items-center gap-4 hover:border-[#00ff41]/80">
                                        <div className="flex-1">
                                            <h4 className="text-xl font-bold">{step.title}</h4>
                                            <p className="text-sm text-[#00ff41]/70">{step.shortDescription}</p>
                                        </div>
                                        <button onClick={() => setSelectedStep(step)} className="bg-black/50 border border-[#00ff41] px-4 py-1 text-sm hover:bg-[#00ff41] hover:text-black transition-colors">
                                            Show Me How
                                        </button>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <div>
                             <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mb-4">
                                <h3 className="text-2xl">Advanced ADB Commands</h3>
                                <button onClick={handleCopyAllCommands} className="bg-black/20 border-2 border-[#00ff41] px-4 py-1 text-sm uppercase tracking-widest hover:bg-[#00ff41] hover:text-black transition-all duration-300 btn-hover-pulse">
                                    Copy All Commands
                                </button>
                             </div>
                             <div className="p-4 bg-black/20 border border-[#00ff41]/20 space-y-3">
                                 <p className="text-yellow-300 text-sm">
                                     <span className="font-bold">WARNING:</span> For advanced users only. Requires PC connection.
                                 </p>
                                 <div className="relative">
                                    <pre className="bg-black/50 border border-[#00ff41]/30 p-4 h-64 overflow-y-auto scrollbar-thin whitespace-pre-wrap break-words font-mono text-sm">
                                       {plan.adbCommands}
                                   </pre>
                                   <CopyToClipboardButton textToCopy={plan.adbCommands} />
                                </div>
                             </div>
                        </div>
                    </div>
                )}
            </div>

            {selectedStep && (
                 <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4" onClick={() => setSelectedStep(null)}>
                    <div className="panel-glass p-6 max-w-2xl w-full max-h-[90vh] overflow-y-auto scrollbar-thin space-y-4" onClick={(e) => e.stopPropagation()}>
                        <h3 className="text-3xl font-bold">{selectedStep.title}</h3>
                        <pre className="whitespace-pre-wrap break-words text-base font-sans bg-black/30 p-4 border border-[#00ff41]/20">
                            {selectedStep.detailedSteps}
                        </pre>
                        <Button onClick={() => setSelectedStep(null)} className="w-full">Close Guide</Button>
                    </div>
                 </div>
            )}
        </section>
    );
};

