class ErrorBoundary extends Component<{children: ReactNode}, {hasError: boolean}> {
  constructor(props: any) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() { return { hasError: true }; }
  componentDidCatch(error: Error, info: ErrorInfo) { console.error("Uncaught error:", error, info); }
  render() {
    if (this.state.hasError) {
      return (
        <div className="h-screen bg-black flex flex-col items-center justify-center p-6 text-center text-[#00ff41] font-mono">
          <h1 className="text-4xl font-bold mb-4">CRITICAL SYSTEM FAILURE</h1>
